        <v-data-table v-model:items-per-page="itemsPerPage" v-model:page="page" v-model:sort-by="sortBy" v-model:expanded="expandedFareSegmentIds" item-value="id" :headers="headers" :items="fareSegments" :search="search" :loading="loading" :items-per-page-options="[5,10,15,25]" items-per-page-text="Elementos por página" no-data-text="No hay tramos configurados" loading-text="Cargando tramos..." class="segments-table">
          <template #loading><v-skeleton-loader type="table-row@5"/></template>
          <template #[`item.originLocationName`]="{item}"><div class="place-cell"><div class="place-avatar"><v-img :src="getImageUrl(item.originLocationImage)" class="place-photo" width="36" height="36" cover><template #error><div class="image-fallback"><v-icon size="17">mdi-map-marker-outline</v-icon></div></template></v-img></div><div><strong>{{ item.originLocationName||'Sin origen' }}</strong><small>Parada {{ item.originStopOrder||'-' }} · {{ area(item,'origin') }}</small></div></div></template>
          <template #[`item.destinationLocationName`]="{item}"><div class="place-cell"><div class="place-avatar"><v-img :src="getImageUrl(item.destinationLocationImage)" class="place-photo" width="36" height="36" cover><template #error><div class="image-fallback"><v-icon size="17">mdi-map-marker-outline</v-icon></div></template></v-img></div><div><strong>{{ item.destinationLocationName||'Sin destino' }}</strong><small>Parada {{ item.destinationStopOrder||'-' }} · {{ area(item,'destination') }}</small></div></div></template>
          <template #[`item.base_price`]="{item}"><span class="price-badge">{{ formatCurrency(item.base_price) }}</span></template>
          <template #[`item.valid_from`]="{item}"><div class="validity"><strong>{{ formatDate(item.valid_from)||'Sin inicio' }}</strong><small>hasta {{ formatDate(item.valid_to)||'indefinida' }}</small></div></template>
          <template #[`item.priority`]="{item}"><span class="priority">{{ item.priority||1 }}</span></template>
          <template #[`item.active`]="{item}"><span class="status" :class="truthy(item.active)?'active':'inactive'"><i/>{{ truthy(item.active)?'Activo':'Inactivo' }}</span></template>
          <template #[`item.actions`]="{item}"><div class="actions"><v-tooltip text="Ver precios por pasajero" location="top"><template #activator="{props}"><v-btn v-bind="props" :icon="isFareSegmentExpanded(item)?'mdi-chevron-up':'mdi-ticket-outline'" variant="text" size="small" class="tickets" @click="toggleFareSegmentExpanded(item)"/></template></v-tooltip><v-tooltip text="Editar tramo" location="top"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-pencil-outline" variant="text" size="small" class="edit" @click="editItem(item)"/></template></v-tooltip><v-tooltip text="Eliminar tramo" location="top"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-trash-can-outline" variant="text" size="small" class="delete" @click="deleteItem(item)"/></template></v-tooltip></div></template>
