      <v-card-text class="dialog-body"><div class="section-label">Recorrido del tramo</div><v-row dense><v-col cols="12" md="6"><v-autocomplete v-model="editedItem.origin_route_stop_id" :items="originStops" :item-title="routeStopLabel" item-value="id" label="Origen" prepend-inner-icon="mdi-map-marker-up-outline" variant="outlined" density="comfortable" no-data-text="No hay paradas de subida" :rules="selectRules" class="stop-select"><template #item="{props,item}"><StopOption :props="props" :item="item.raw" :src="getImageUrl(item.raw.locationImage)"/></template></v-autocomplete></v-col><v-col cols="12" md="6"><v-autocomplete v-model="editedItem.destination_route_stop_id" :items="destinationStops" :item-title="routeStopLabel" item-value="id" label="Destino" prepend-inner-icon="mdi-map-marker-down-outline" variant="outlined" density="comfortable" no-data-text="No hay paradas de bajada" :rules="selectRules" class="stop-select"><template #item="{props,item}"><v-list-item v-bind="props" class="stop-option"><template #prepend><v-avatar size="36" rounded="lg" class="option-avatar"><v-img :src="getImageUrl(item.raw.locationImage)" width="36" height="36" cover/></v-avatar></template><v-list-item-title>{{ routeStopLabel(item.raw) }}</v-list-item-title><v-list-item-subtitle>{{ [item.raw.locationCity,item.raw.locationCountry].filter(Boolean).join(', ') }}</v-list-item-subtitle></v-list-item></template></v-autocomplete></v-col></v-row>
      <div class="section-label spaced">Precio y vigencia</div><v-row dense><v-col cols="12" md="3"><v-text-field v-model.number="editedItem.base_price" label="Precio base" prefix="$" prepend-inner-icon="mdi-cash" variant="outlined" density="comfortable" type="number" min="0" :rules="numberRules"/></v-col><v-col cols="12" md="3"><v-text-field v-model="editedItem.valid_from" label="Vigente desde" prepend-inner-icon="mdi-calendar-start" variant="outlined" density="comfortable" type="date" :min="editedIndex===-1?todayYmd:undefined"/></v-col><v-col cols="12" md="3"><v-text-field v-model="editedItem.valid_to" label="Vigente hasta" prepend-inner-icon="mdi-calendar-end" variant="outlined" density="comfortable" type="date" :min="editedItem.valid_from||todayYmd"/></v-col><v-col cols="12" md="3"><v-text-field v-model.number="editedItem.priority" label="Prioridad" prepend-inner-icon="mdi-sort-numeric-ascending" variant="outlined" density="comfortable" type="number" min="1" :rules="priorityRules"/></v-col></v-row>
      <div class="active-control"><div><strong>Estado del tramo</strong><small>Los tramos inactivos no estarán disponibles para nuevas ventas.</small></div><div :class="truthy(editedItem.active)?'active-text':'inactive-text'"><span>{{ truthy(editedItem.active)?'Activo':'Inactivo' }}</span><v-switch v-model="editedItem.active" color="success" hide-details inset/></div></div>
      <div class="ticket-section"><div class="ticket-section-header"><div><div class="section-label">Precios por tipo de pasajero</div><p>Configura el valor específico de cada categoría habilitada.</p></div><v-btn v-if="hasMoreFareSegmentTicketTypes" variant="tonal" color="primary" size="small" prepend-icon="mdi-plus" @click="addFareSegmentTicketType">Agregar tipo</v-btn></div><div v-if="editedItem.fareSegmentTicketTypes.length" class="ticket-editor"><div v-for="(ticket,index) in editedItem.fareSegmentTicketTypes" :key="fareSegmentTicketTypeKey(ticket,index)" class="ticket-editor-row"><div class="ticket-name"><v-icon size="17">mdi-ticket-outline</v-icon><strong>{{ ticket.ticketTypeName||'Tipo de pasajero' }}</strong></div><v-text-field v-model.number="ticket.base_price" label="Precio" prefix="$" type="number" min="0" variant="outlined" density="compact" hide-details="auto" :rules="ticket.active?ticketTypePriceRules(ticket):[]" :disabled="ticket.active===false"/><div class="ticket-toggle" :class="ticket.active!==false?'enabled-text':'disabled-text'"><span>{{ ticket.active!==false?'Habilitado':'Deshabilitado' }}</span><v-switch v-model="ticket.active" color="success" hide-details inset @update:model-value="onTicketTypeActiveChange"/></div></div></div><div v-else class="empty-ticket-types"><v-icon size="24">mdi-ticket-off-outline</v-icon>No hay tipos de pasajero disponibles.</div></div>
      </v-card-text><v-divider/><v-card-actions class="dialog-actions"><v-btn variant="text" class="cancel" :disabled="loading" @click="close">Cancelar</v-btn><v-btn type="submit" class="save" elevation="0" :loading="loading" :disabled="!valid">{{ editedIndex===-1?'Crear tramo':'Guardar cambios' }}</v-btn></v-card-actions></v-card></v-form></v-dialog>

    <v-dialog v-model="dialogDelete" max-width="430" persistent><v-card class="delete-dialog" elevation="0"><div class="delete-icon"><v-icon size="27">mdi-trash-can-outline</v-icon></div><h3>Eliminar tramo</h3><p>¿Deseas eliminar el tramo entre <strong>{{ editedItem.originLocationName||'el origen' }}</strong> y <strong>{{ editedItem.destinationLocationName||'el destino' }}</strong>? Esta acción no se puede deshacer.</p><div><v-btn variant="text" class="cancel" :disabled="loading" @click="closeDelete">Cancelar</v-btn><v-btn class="delete-confirm" elevation="0" :loading="loading" @click="deleteItemConfirm">Eliminar</v-btn></div></v-card></v-dialog>
  </div>
</template>

<script>
import { h } from "vue";
import { VAvatar, VIcon, VImg, VListItem, VListItemSubtitle, VListItemTitle } from "vuetify/components";
import { handleRequest } from "@/utils/api";
import LocalStorageService from "@/LocalStorageService";
const StopOption={props:{props:Object,item:Object,src:String},setup(p){return()=>h(VListItem,{...p.props,class:"stop-option"},{prepend:()=>h(VAvatar,{size:36,rounded:"lg",class:"option-avatar"},()=>h(VImg,{src:p.src,width:36,height:36,cover:true})),default:()=>[h(VListItemTitle,null,()=>`${p.item.stop_order}. ${p.item.locationName||"Sin nombre"}`),h(VListItemSubtitle,null,()=>[p.item.locationCity,p.item.locationCountry].filter(Boolean).join(", "))]})}};
export default{
  name:"FareSegment",components:{StopOption},emits:["close"],props:{route:{type:Object,required:true,default:()=>({})}},
  data:()=>({snackbar:false,sb_type:"",sb_message:"",sb_timeout:2000,sb_title:"",sb_icon:"",valid:false,loading:false,dialog:false,dialogDelete:false,search:"",page:1,itemsPerPage:10,sortBy:[],company_id:"",route_id:"",routeStops:[],ticketTypes:[],fareSegments:[],expandedFareSegmentIds:[],editedIndex:-1,
    headers:[{title:"Origen",key:"originLocationName",sortable:true,width:"22%"},{title:"Destino",key:"destinationLocationName",sortable:true,width:"22%"},{title:"Precio",key:"base_price",sortable:true,width:"12%"},{title:"Vigencia",key:"valid_from",sortable:true,width:"16%"},{title:"Prioridad",key:"priority",sortable:true,width:"9%"},{title:"Estado",key:"active",sortable:true,width:"10%"},{title:"",key:"actions",sortable:false,align:"end",width:"9%"}],
    editedItem:{id:"",company_id:"",route_id:"",origin_route_stop_id:"",destination_route_stop_id:"",base_price:0,currency:"CLP",valid_from:"",valid_to:"",priority:1,active:true,fareSegmentTicketTypes:[]},defaultItem:{id:"",company_id:"",route_id:"",origin_route_stop_id:"",destination_route_stop_id:"",base_price:0,currency:"CLP",valid_from:"",valid_to:"",priority:1,active:true,fareSegmentTicketTypes:[]},originalItem:{},selectRules:[v=>!!v||"Debes seleccionar una parada"],numberRules:[v=>v!==null&&v!==undefined&&v!==""||"El precio es requerido",v=>!Number.isNaN(Number(v))||"Debe ser un número válido",v=>Number(v)>=0||"No puede ser negativo"],priorityRules:[v=>Number(v)>=1||"Debe ser mayor o igual a 1"]}),
  computed:{formTitle(){return this.editedIndex===-1?"Agregar tramo":"Editar tramo"},routeTitle(){return this.route?.name?`Tramos de ${this.route.name}`:"Tramos tarifarios"},todayYmd(){const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`},destinationStops(){return this.routeStops.filter(x=>this.canBeDestinationStop(x)&&Number(x.id)!==Number(this.editedItem.origin_route_stop_id))},originStops(){return this.routeStops.filter(x=>this.canBeOriginStop(x)&&Number(x.id)!==Number(this.editedItem.destination_route_stop_id))},hasMoreFareSegmentTicketTypes(){return this.ticketTypes.some(t=>!this.editedItem.fareSegmentTicketTypes.some(x=>Number(x.ticket_type_id)===Number(t.id)))},activeSegments(){return this.fareSegments.filter(x=>this.truthy(x.active)).length},countText(){return this.fareSegments.length===1?"1 tramo configurado":`${this.fareSegments.length} tramos configurados`}},
  watch:{route:{deep:true,immediate:true,handler(v){this.company_id=v?.company_id||this.storage("business_id");this.route_id=v?.route_id||v?.id||"";if(this.route_id)this.initialize()}},search(){this.page=1},"editedItem.origin_route_stop_id"(){if(this.editedItem.destination_route_stop_id&&!this.destinationStops.some(x=>Number(x.id)===Number(this.editedItem.destination_route_stop_id)))this.editedItem.destination_route_stop_id=""},"editedItem.valid_from"(v){if(v&&this.editedItem.valid_to&&v>this.editedItem.valid_to)this.editedItem.valid_to=""}},
  methods:{storage(k){return String(LocalStorageService.getItem(k)??"").replace(/["']/g,"").trim()},truthy(v){return v===true||v===1||v==="1"},unwrap(v){return v?.raw??v??{}},clone(v){return JSON.parse(JSON.stringify(v))},getImageUrl(src){const image=String(src||"locations/default.jpg");if(/^https?:/i.test(image))return image;const base=String(this.$axios.defaults.baseURL||"");const clean=image.replace(/^\/+/,"");return clean.startsWith("images/")?`${base}${clean}`:`${base}images/${clean}`},getRouteStopById(id){return this.routeStops.find(x=>Number(x.id)===Number(id))},routeStopLabel(s){return s?`${s.stop_order}. ${s.locationName||s.address||"Sin nombre"}`:""},canBeOriginStop(s){return this.truthy(s?.allows_boarding)},canBeDestinationStop(s){return this.truthy(s?.allows_alighting)},area(item,prefix){return[item[`${prefix}LocationCity`],item[`${prefix}LocationCountry`]].filter(Boolean).join(", ")||"Sin localidad"},formatCurrency(v){return new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(Number(v)||0)},formatDate(v){if(!v)return"";const [y,m,d]=String(v).slice(0,10).split("-");return y&&m&&d?`${d}/${m}/${y}`:String(v)},fareSegmentTicketTypeKey(t,i){return t?.id?`ticket-${t.id}`:`ticket-${t?.ticket_type_id??i}`},isFareSegmentExpanded(x){return this.expandedFareSegmentIds.includes(Number(x.id))},toggleFareSegmentExpanded(x){this.expandedFareSegmentIds=this.isFareSegmentExpanded(x)?[]:[Number(x.id)]},
    normalizeRouteStop(s={}){return{...s,id:s.id,location_id:s.location_id??s.locationId??"",locationName:s.locationName??s.location_name??"",locationCity:s.locationCity??s.location_city??"",locationCountry:s.locationCountry??s.location_country??"",locationImage:s.locationImage??s.location_image??"locations/default.jpg",stop_order:s.stop_order??s.stopOrder??"",allows_boarding:s.allows_boarding??s.allowsBoarding??s.subida??false,allows_alighting:s.allows_alighting??s.allowsAlighting??s.bajada??false,active:s.active??true}},
    normalizeRelations(rows=[]){return(Array.isArray(rows)?rows:[]).map(r=>({id:r.id??"",fare_segment_id:r.fare_segment_id??r.fareSegmentId??"",ticket_type_id:r.ticket_type_id??r.ticketTypeId??"",base_price:r.base_price??r.basePrice??0,active:r.active??true,ticketTypeName:r.ticketTypeName??r.ticketType?.name??""}))},normalizeTicketType(t={}){return{...t,id:t.id,ticketTypeName:t.ticketTypeName??t.ticket_type_name??t.name??"",active:t.active??true}},getTicketTypes(data={}){if(Array.isArray(data))return data;return data.tickettypes??data.ticketTypes??data.ticket_types??Object.values(data.tickettypes||data.ticketTypes||data.ticket_types||{})},
    buildRows(relations=[],definitions=this.ticketTypes){const map=new Map((Array.isArray(relations)?relations:[]).map(r=>[Number(r.ticket_type_id),r]));return definitions.map(t=>{const r=map.get(Number(t.id));return{id:r?.id??"",ticket_type_id:t.id,ticketTypeName:t.ticketTypeName||t.name||"",base_price:r?.base_price!=null?Number(r.base_price):0,active:r?.active??t.active??true}})},normalizeSegment(item={}){const o=this.getRouteStopById(item.origin_route_stop_id),d=this.getRouteStopById(item.destination_route_stop_id),relations=item.fare_segment_ticket_types??item.fareSegmentTicketTypes??[];return{...item,company_id:item.company_id??this.company_id,route_id:item.route_id??this.route_id,base_price:item.base_price??0,currency:item.currency??"CLP",valid_from:item.valid_from??"",valid_to:item.valid_to??"",priority:item.priority??1,active:item.active??true,originLocationName:item.originLocationName||o?.locationName||item.originName||"",originLocationCity:item.originLocationCity||o?.locationCity||"",originLocationCountry:item.originLocationCountry||o?.locationCountry||"",originLocationImage:item.originLocationImage||o?.locationImage||"locations/default.jpg",originStopOrder:item.originStopOrder??o?.stop_order??"",destinationLocationName:item.destinationLocationName||d?.locationName||item.destinationName||"",destinationLocationCity:item.destinationLocationCity||d?.locationCity||"",destinationLocationCountry:item.destinationLocationCountry||d?.locationCountry||"",destinationLocationImage:item.destinationLocationImage||d?.locationImage||"locations/default.jpg",destinationStopOrder:item.destinationStopOrder??d?.stop_order??"",fare_segment_ticket_types:this.normalizeRelations(relations),fareSegmentTicketTypes:this.buildRows(relations)}},
    buildPayloadRows(){return this.editedItem.fareSegmentTicketTypes.map(t=>{const p={ticket_type_id:t.ticket_type_id,base_price:Number(t.base_price??0),active:t.active??true};if(t.id)p.id=t.id;return p})},ticketTypePriceRules(t){return[v=>t.active===false||(v!==""&&v!=null)||"El precio es obligatorio",v=>t.active===false||!Number.isNaN(Number(v))||"Debe ser un número válido",v=>t.active===false||Number(v)>=0||"No puede ser negativo"]},onTicketTypeActiveChange(){this.$nextTick(()=>this.$refs.form?.validate?.())},addFareSegmentTicketType(){const t=this.ticketTypes.find(x=>!this.editedItem.fareSegmentTicketTypes.some(r=>Number(r.ticket_type_id)===Number(x.id)));if(t)this.editedItem.fareSegmentTicketTypes.push({id:"",ticket_type_id:t.id,ticketTypeName:t.ticketTypeName||t.name||"",base_price:0,active:true})},
    async loadTicketTypes(force=false){if(!force&&this.ticketTypes.length)return;const r=await handleRequest({endpoint:"get-ticket-type",method:"GET"});this.ticketTypes=r.success?this.getTicketTypes(r.data).map(x=>this.normalizeTicketType(x)):[]},async loadRouteStops(){if(!this.route_id){this.routeStops=[];return}const embedded=Array.isArray(this.route?.routeStops)?this.route.routeStops:Array.isArray(this.route?.route_stops)?this.route.route_stops:[];if(embedded.length){this.routeStops=embedded.map(x=>this.normalizeRouteStop(x));return}const r=await handleRequest({endpoint:"route-stop-by-route",method:"POST",data:{route_id:this.route_id}});const raw=r.success?(Array.isArray(r.data?.routeStops)?r.data.routeStops:Object.values(r.data?.routeStops||{})):[];this.routeStops=raw.map(x=>this.normalizeRouteStop(x))},async loadFareSegments(){const r=await handleRequest({endpoint:"fare-segment-by-route",method:"POST",data:{route_id:this.route_id}});const raw=r.success?(Array.isArray(r.data?.fareSegments)?r.data.fareSegments:Object.values(r.data?.fareSegments||{})):[];this.fareSegments=raw.map(x=>this.normalizeSegment(x)).sort((a,b)=>Number(a.priority)-Number(b.priority))},async initialize(){if(!this.route_id)return;this.loading=true;try{await this.loadTicketTypes();await this.loadRouteStops();await this.loadFareSegments()}catch(e){this.showAlert("error","Ocurrió un error al cargar los tramos.",3000)}finally{this.loading=false}},
    reset(){this.editedItem=this.clone(this.defaultItem);this.originalItem=this.clone(this.defaultItem);this.editedIndex=-1;this.valid=false},async showAdd(){try{await this.loadTicketTypes(true);if(!this.routeStops.length)await this.loadRouteStops();this.reset();this.editedItem={...this.clone(this.defaultItem),company_id:this.company_id,route_id:this.route_id,fareSegmentTicketTypes:this.buildRows()};this.dialog=true;this.$nextTick(()=>this.$refs.form?.resetValidation())}catch(e){this.showAlert("error","No fue posible cargar los catálogos.",3000)}},close(){if(this.loading)return;this.dialog=false;this.$nextTick(()=>{this.reset();this.$refs.form?.resetValidation()})},hasDuplicateFareSegment(o,d){return this.fareSegments.some(x=>Number(x.id)!==Number(this.editedItem.id||0)&&Number(x.origin_route_stop_id)===Number(o)&&Number(x.destination_route_stop_id)===Number(d))},validateSegment(){const o=this.getRouteStopById(this.editedItem.origin_route_stop_id),d=this.getRouteStopById(this.editedItem.destination_route_stop_id);if(!o||!d){this.showAlert("warning","Selecciona un origen y un destino válidos.",3000);return false}if(Number(o.stop_order)>=Number(d.stop_order)){this.showAlert("warning","El origen debe estar antes que el destino.",3000);return false}if(this.hasDuplicateFareSegment(o.id,d.id)){this.showAlert("warning","Ya existe un tramo con ese origen y destino.",3000);return false}if(this.editedItem.fareSegmentTicketTypes.some(t=>t.active!==false&&(t.base_price===""||t.base_price==null||Number.isNaN(Number(t.base_price))||Number(t.base_price)<0))){this.showAlert("warning","Cada tipo habilitado debe tener un precio válido.",3000);return false}if(this.editedItem.valid_from&&this.editedItem.valid_to&&this.editedItem.valid_from>this.editedItem.valid_to){this.showAlert("warning","La fecha inicial no puede superar la fecha final.",3000);return false}return true},
    async save(){const validation=await this.$refs.form?.validate();if(!validation?.valid||!this.validateSegment())return;const creating=this.editedIndex===-1,payload={company_id:this.company_id,route_id:this.route_id,origin_route_stop_id:this.editedItem.origin_route_stop_id,destination_route_stop_id:this.editedItem.destination_route_stop_id,base_price:Number(this.editedItem.base_price),currency:"CLP",valid_from:this.editedItem.valid_from,valid_to:this.editedItem.valid_to,priority:Number(this.editedItem.priority)||1,active:this.editedItem.active??true,service_class:null,fareSegmentTicketTypes:this.buildPayloadRows()};if(!creating)payload.id=this.editedItem.id;this.loading=true;try{const r=await handleRequest({endpoint:"fare-segment",method:creating?"POST":"PUT",data:payload});if(r.success){this.dialog=false;this.showAlert("success",r.message||"Tramo guardado correctamente.",3000);await this.initialize();this.reset()}else this.showAlert("warning",r.message||"No fue posible guardar el tramo.",3000)}catch(e){this.showAlert("error","Ocurrió un error al guardar el tramo.",3000)}finally{this.loading=false}},async editItem(item){try{await this.loadTicketTypes(true);if(!this.routeStops.length)await this.loadRouteStops();const segment=this.normalizeSegment(this.unwrap(item));this.editedIndex=this.fareSegments.findIndex(x=>String(x.id)===String(segment.id));this.originalItem=this.clone(segment);this.editedItem=this.clone(segment);this.dialog=true;this.$nextTick(()=>this.$refs.form?.resetValidation())}catch(e){this.showAlert("error","No fue posible cargar el tramo.",3000)}},deleteItem(item){const x=this.unwrap(item);this.editedItem={...this.defaultItem,...x};this.dialogDelete=true},closeDelete(){if(!this.loading){this.dialogDelete=false;this.reset()}},async deleteItemConfirm(){this.loading=true;try{const r=await handleRequest({endpoint:"fare-segment-destroy",method:"POST",data:{id:this.editedItem.id}});if(r.success){this.dialogDelete=false;this.showAlert("success",r.message||"Tramo eliminado correctamente.",3000);await this.initialize();this.reset()}else this.showAlert("warning",r.message||"No fue posible eliminar el tramo.",3000)}catch(e){this.showAlert("error","Ocurrió un error al eliminar el tramo.",3000)}finally{this.loading=false}},showAlert(type,message,timeout=3000){const cfg={success:["Éxito","mdi-check-circle"],warning:["Advertencia","mdi-alert-circle"],error:["Error","mdi-close-circle"]}[type]||["Información","mdi-information"];this.sb_type=type;this.sb_title=cfg[0];this.sb_icon=cfg[1];this.sb_message=message;this.sb_timeout=timeout;this.snackbar=true}
  }
}
</script>

